<div class="container"><div class="page-heading d-flex flex-wrap justify-content-between align-items-end gap-3"><div><span class="section-kicker">Ruang warga</span><h1>Halo, <?= e(current_user()['name']) ?></h1><p>Pantau perjalanan layanan surat Anda.</p></div><a class="btn btn-success" href="/ajukan-surat">Ajukan surat</a></div><div class="row g-4"><div class="col-lg-8"><section class="data-panel"><h2 class="h5 mb-3">Riwayat pengajuan</h2><?php if (!$applications): ?><div class="empty-state">Belum ada pengajuan surat.</div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Jenis surat</th><th>Status</th><th>Tanggal</th><th></th></tr></thead><tbody><?php foreach ($applications as $application): ?><tr><td><?= e($application['type_name']) ?></td><td><span class="status-pill <?= in_array($application['status'], ['rejected', 'cancelled'], true) ? 'danger' : (in_array($application['status'], ['issued', 'ready_pickup', 'picked_up'], true) ? 'success' : 'pending') ?>"><?= e(status_label($application['status'])) ?></span></td><td><?= e(date('d/m/Y', strtotime($application['created_at']))) ?></td><td><a href="/pengajuan/<?= (int) $application['id'] ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div><div class="col-lg-4"><section class="data-panel"><h2 class="h5 mb-3">Pemberitahuan</h2><?php if (!$notifications): ?><p class="small text-secondary mb-0">Belum ada pemberitahuan.</p><?php else: foreach ($notifications as $notification): ?><div class="border-top py-3"><p class="small mb-1"><?= e($notification['message']) ?></p><small class="text-secondary"><?= e(date('d/m/Y H:i', strtotime($notification['created_at']))) ?></small></div><?php endforeach; endif; ?></section></div></div></div>